#[capability(
    module = "zoho-crm",
    id = "execute-coql-query",
    display_name = r##"Retrieve records using a COQL query"##,
    description = r##"To retrieve records from one or more Zoho CRM modules using a COQL SELECT query, with support for cross-module joins, aggregate functions, and flexible filtering."##
)]
pub async fn execute_coql_query(
    input: ExecuteCoqlQueryInput,
) -> Result<ExecuteCOQLQuery200Response, AgentError> {
    let connection = kit::require_connection(&input._connection, "ZOHO")?;
    input.request()?.send(connection, "ZOHO").await
}

impl ExecuteCoqlQueryInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = String::from("/crm/v8/coql");
        let request = kit::Request::new("POST", path);
        request.json_body(
            kit::Body::new()
                .field_opt("include_meta", &self.include_meta)
                .field("select_query", &self.select_query),
            "ZOHO",
        )
    }
}

