#[capability(
    module = "zoho-crm",
    id = "get-modules",
    display_name = r##"Retrieve modules"##,
    description = r##"Retrieves the list of all modules available in the Zoho CRM account, including standard, custom, subform, and linking (MxN) modules. Supports optional filtering by `status`, `feature_name`, and `include` to control the scope and depth of the response. When both `status` and `feature_name` are provided, modules must satisfy both criteria. Returns all matching modules in a single response without pagination."##
)]
pub async fn get_modules(input: GetModulesInput) -> Result<GetModules200Response, AgentError> {
    let connection = kit::require_connection(&input._connection, "ZOHO")?;
    input.request()?.send(connection, "ZOHO").await
}

impl GetModulesInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = String::from("/crm/v8/settings/modules");
        let request = kit::Request::new("GET", path)
            .query_opt("status", &self.status)
            .query_opt("feature_name", &self.feature_name)
            .query_opt("include", &self.include)
            .query_opt("fields", &self.fields);
        Ok(request)
    }
}

